        expected_count: int | None = None
        running_crc = 0

        def feed(block: bytes, *, final: bool = False) -> None:
            # Verify the seal incrementally and index every entry line; only offsets survive.
            nonlocal running_crc, seen, previous, expected_count
            if block:
                running_crc = zlib.crc32(block, running_crc)
        try:
            with open(path, "rb") as handle:
                handle.seek(0)
                header_bytes = handle.readline()
                if not header_bytes or not header_bytes.endswith(b"\n") or handle.tell() > prefix_len:
                    raise CorruptionError("missing or overlong header", path=path)
                feed(header_bytes)
                try:
                    header = json.loads(header_bytes[:-1].decode("utf-8"))
                except (json.JSONDecodeError, UnicodeDecodeError) as error:
                    raise CorruptionError("unreadable header", path=path) from error
                if not isinstance(header, dict):
                    raise CorruptionError("header must be an object", path=path)
                try:
                    bloom_bits = int(header["bloomBits"])  # type: ignore[arg-type]
                    bloom_hashes = int(header["bloomHashes"])  # type: ignore[arg-type]
                    expected_count = int(header["count"])  # type: ignore[arg-type]
                except (KeyError, TypeError, ValueError) as error:
                    raise CorruptionError("header field is missing or not an integer", path=path) from error
                if bloom_bits <= 0 or bloom_hashes <= 0 or expected_count < 0:
                    raise CorruptionError("header fields must be positive", path=path)
                while True:
                    offset = handle.tell()
                    if offset >= prefix_len:
                        break
                    offsets.append(offset)
                    line = handle.readline()
                    if not line.endswith(b"\n") or handle.tell() > prefix_len:
                        raise CorruptionError("entry line is unterminated", path=path, line=seen + 1)
                    feed(line)
                    entry = line[:-1]
                    tab = entry.find(b"\t")
                    if tab <= 0:
                        raise CorruptionError("entry without a separator", path=path, line=seen + 1)
                    key_bytes, encoded_bytes = entry[:tab], entry[tab + 1 :]
                    if not key_bytes:
                        raise CorruptionError("entry has an empty key", path=path, line=seen + 1)
                    try:
                        key = key_bytes.decode("utf-8")
                    except UnicodeDecodeError as error:
                        raise CorruptionError("entry key must be UTF-8", path=path, line=seen + 1) from error
                    if previous is not None and key <= previous:
                        raise CorruptionError("entries must be strictly ascending and unique", path=path, line=seen + 1, key=key)
                    try:
                        encoded = encoded_bytes.decode("ascii")
                    except UnicodeDecodeError as error:
                        raise CorruptionError("entry payload must be ASCII base64", path=path, line=seen + 1) from error
                    _decode_value(encoded, path=path, line=seen + 1)
                    previous = key
                    seen += 1
            if expected_count != seen:
                raise CorruptionError(
                    "entry count differs from the header",
                    path=path,
                    expected=expected_count,
                    found=seen,
                )
            if format(running_crc & 0xFFFFFFFF, "08x") != footer["crc32"]:
                raise CorruptionError("table checksum mismatch", path=path)
            bloom = BloomFilter.loads(bloom_bits, bloom_hashes, str(footer["bloom"]))
        except CorruptionError:
            raise
        except (OSError, ValueError) as error:
            raise CorruptionError("table could not be parsed", path=path) from error
        return cls(path=path, bloom=bloom, count=seen, offsets=offsets)

    # -- reads ---------------------------------------------------------------
    def _read_entry(self, handle: object, slot: int, *, full_value: bool) -> tuple[str, str | None]:
        offset = int(self.offsets[slot])
        handle.seek(offset)
        if full_value:
            line = handle.readline()
        else:
            # Only the data needed to answer a point lookup: the key plus the value marker.
            line = handle.readline(MAX_READ + 256) if False else _read_bounded(handle)
        if not line.endswith(b"\n"):
            line = handle.readline()
        entry = line[:-1]
        tab = entry.find(b"\t")
        line_no = slot + 2  # header is line 1
        try:
            key = entry[:tab].decode("utf-8")
        except UnicodeDecodeError as error:
            raise CorruptionError("entry key must be UTF-8", path=self.path, line=line_no) from error
        encoded_bytes = entry[tab + 1 :]
        if not full_value:
            # A complete line already arrived only when the value is a tombstone or trivially
            # short; either way decoding the bytes we have is valid (they passed open() checks).
            if not line.endswith(b"\n") and len(encoded_bytes) > MAX_READ:
                if encoded_bytes[:1] == b"~":
                    return key, None
                # Invalid alphabet here means a corrupt file that the seal check should have
                # caught; report it instead of issuing another bounded read.
                try:
                    encoded_bytes[:MAX_READ].decode("ascii")
                except UnicodeDecodeError as error:
                    raise CorruptionError("entry payload must be ASCII base64", path=self.path, line=line_no) from error
                return key, _NEED_VALUE
        try:
            encoded = encoded_bytes.decode("ascii")
        except UnicodeDecodeError as error:
            raise CorruptionError("entry payload must be ASCII base64", path=self.path, line=line_no) from error
        return key, _decode_value(encoded, path=self.path, line=line_no)

    def get(self, key: str) -> tuple[bool, str | None]:
        if not self.bloom.might_contain(key):
            return False, None
        with open(self.path, "rb") as handle:
            lo, hi = 0, len(self.offsets)
            while lo < hi:
                mid = (lo + hi) // 2
                candidate, value = self._read_entry(handle, mid, full_value=False)
                if candidate < key:
                    lo = mid + 1
                elif candidate > key:
                    hi = mid
                else:
                    if value is _NEED_VALUE:
                        _, value = self._read_entry(handle, mid, full_value=True)
                    return True, value
        return False, None

    def scan_rows(
        self,
        start: str | None = None,
        end: str | None = None,
        *,
        stop_key: str | None = None,
    ) -> Iterator[tuple[str, str | None]]:
        """Yield visible rows in key order, streaming one line at a time.

        ``start`` is inclusive, ``end`` exclusive. ``stop_key`` (inclusive) bounds the *entries
        touched*, not the output: k-way merges pass their range upper bound so an iterator stops
        reading once its keys can no longer matter, even when that key itself is a tombstone.
        """
        if not self.count:
            return
        first = 0
        if start is not None:
            first = self._slot_at_or_after(start)
        with open(self.path, "rb") as handle:
            slot = first
            while slot < len(self.offsets):
                key, value = self._read_entry(handle, slot, full_value=True)
                slot += 1
                if stop_key is not None and key > stop_key:
                    return
                if end is not None and key >= end:
                    return
                if start is not None and key < start:
                    continue
                yield key, value

    def _slot_at_or_after(self, key: str) -> int:
        lo, hi = 0, len(self.offsets)
        if hi == 0:
            return 0
        with open(self.path, "rb") as handle:
            while lo < hi:
                mid = (lo + hi) // 2
                candidate, _ = self._read_entry(handle, mid, full_value=False)
                if candidate < key:
                    lo = mid + 1
                else:
                    hi = mid
        return lo

    def items(self) -> list[tuple[str, str | None]]:
        return list(self.scan_rows())

    def to_document(self) -> dict[str, object]:
        return {"path": self.path, "keys": self.count, "bloom": self.bloom.to_document()}


# Sentinel returned by a bounded read: key matched but its value bytes were not read yet.
_NEED_VALUE = object()


def _read_bounded(handle: object) -> bytes:
    return handle.readline(256)  # replaced below; see read construction in _read_entry


def _new_offset_array():
    from array import array

    return array("Q")

