    def _load(self) -> None:
        if self.slot < len(self.table.offsets):
            self.head = self.table._read_full(self.handle, self.slot)
            self.slot += 1
        else:
            self.head = None

    def advance(self) -> None:
        self._load()

    def close(self) -> None:
        self.handle.close()
        self.head = None

