"""Ad-hoc verification: baseline compatibility, bloom short-circuit, bounded reads, early limit."""

from __future__ import annotations

import builtins
import importlib.util
import os
import shutil
import subprocess
import sys
import tempfile
import types

from kvstore.sstable import SSTable
from kvstore.store import Store

REPO = "/mnt/c/dbsvace/vo7/B/task001"


def load_baseline_module(directory: str):
    src = subprocess.run(
        ["git", "show", "HEAD:kvstore/sstable.py"], capture_output=True, text=True, cwd=REPO
    ).stdout
    src = src.replace("from .errors", "from kvstore.errors")
    path = os.path.join(directory, "old_sstable.py")
    with open(path, "w") as handle:
        handle.write(src)
    spec = importlib.util.spec_from_file_location("old_sstable", path)
    module = importlib.util.module_from_spec(spec)
    sys.modules["old_sstable"] = module
    spec.loader.exec_module(module)
    return module


def measure_table_reads(table, entry_start, action):
    real_open = builtins.open
    acc = {"bytes": 0, "calls": 0}

    def counting_open(path, *args, **kwargs):
        handle = real_open(path, *args, **kwargs)
        if str(path) != table.path:
            return handle

        class Wrapper:
            def seek(self, *a):
                return handle.seek(*a)

            def tell(self):
                return handle.tell()

            def read(self, n=-1):
                pos = handle.tell()
                data = handle.read(n)
                if pos >= entry_start:
                    acc["bytes"] += len(data)
                acc["calls"] += 1
                return data

            def close(self):
                return handle.close()

        return Wrapper()

    builtins.open = counting_open
    try:
        action()
    finally:
        builtins.open = real_open
    return acc["bytes"], acc["calls"]


def main() -> None:
    directory = tempfile.mkdtemp()
    baseline = load_baseline_module(directory)

    path = os.path.join(directory, "table-000001.sst")
    items = [("k%04d" % i, ("V" * 100000) if i % 7 else None) for i in range(200)]
    baseline.SSTable.write(path, items)  # resident-values baseline writer

    table = SSTable.open(path)  # new lazy open of an OLD-format table
    assert table.count == 200
    for i in (0, 1, 7, 199):
        key = "k%04d" % i
        expected = None if i % 7 == 0 else "V" * 100000
        assert table.get(key) == (True, expected), key
    assert table.get("nope") == (False, None)
    assert [k for k, _ in table.scan_rows("k0010", "k0014")] == ["k0010", "k0011", "k0012", "k0013"]

    entry_start = table.offsets[0]
    miss_bytes, miss_calls = measure_table_reads(table, entry_start, lambda: table.get("definitely-absent-zzz"))
    hit_bytes, hit_calls = measure_table_reads(table, entry_start, lambda: table.get("k0199"))
    print(f"bloom miss: entry bytes={miss_bytes} calls={miss_calls}")
    print(f"hit 100KB value: entry bytes={hit_bytes} calls={hit_calls}")
    assert miss_bytes == 0, "bloom miss must not touch the entry region"
    assert hit_bytes < 5000, "a point hit must not pull the whole value"

    store_dir = tempfile.mkdtemp()
    shutil.copy(path, os.path.join(store_dir, os.path.basename(path)))
    with Store(store_dir).open() as store:
        first_offset = store.tables[0].offsets[0]
        totals = {"bytes": 0}
        real_open = builtins.open

        def counting_open(p, *args, **kwargs):
            handle = real_open(p, *args, **kwargs)
            if not str(p).endswith(".sst"):
                return handle

            class Wrapper:
                def seek(self, *a):
                    return handle.seek(*a)

                def tell(self):
                    return handle.tell()

                def read(self, n=-1):
                    pos = handle.tell()
                    data = handle.read(n)
                    if pos >= first_offset:
                        totals["bytes"] += len(data)
                    return data

                def close(self):
                    return handle.close()

            return Wrapper()

        builtins.open = counting_open
        try:
            rows = store.scan(limit=1)
        finally:
            builtins.open = real_open
        print(f"scan limit=1: {len(rows)} row, entry bytes={totals['bytes']}")
        assert len(rows) == 1
        assert totals["bytes"] < 200000, "limit must stop reading after enough visible rows"
        visible = 200 - (200 // 7)
        assert len(store.scan()) == visible
    print("ALL LAZINESS CHECKS PASS")


if __name__ == "__main__":
    main()

